def solve(inp,H,W=None):
    if W is None:
        H,W=len(inp),len(inp[0])
    cnt=Counter(x for r in inp for x in r)
    bgc=max(cnt,key=cnt.get)
    cells=[]
    for v in sorted(cnt):
        if v==bgc: continue
        pts=[(i,j) for i in range(H) for j in range(W) if inp[i][j]==v]
        cells.append((v,bgc,len(pts),pts))
    # assume exactly two multi-cell colors are our segments
    segs=sorted([(c[2],c[0],c[3]) for c in cells if len(c[3])>1], key=lambda t:(t[1],t[0]))
    A,B=segs
    def clean(i,j): return 0<=i<H and 0<=j<W and inp[i][j]==bgc
    # orientation vertical
    out=[row[:] for row in inp]
    Acols={c[0][1]:A[2]}, Bcols={B[0][1]:B[2]}
    ca,cb={p[1] for p in A[2]},{p[1] for p in B[2]}
    ra,rb=min(p[0] for p in A[2]),max(p[0] for p in A[2]),min(p[0] for p in B[2]),max(p[0] for p in B[2])
    # corridor row r from A_col to B_col, inclusive, fully clean; legs from segment ends to corridor clean
    best=None
    for r in range(H):
        c0,c1=min(ca),max(cb)
        ok=True
        for cc in range(c0,c1+1):
            if not clean(r,cc): ok=False;break
        if not ok: continue
        # legs: from topmost cell of each segment up to r (or from bottom)
        legok=True
        for S,end in [(A,ra),(B,rb)]:
            for s in [S[0],S[-1]]:
                r2=r if r!=s else None
                step=1 if (r2>s)>0 else -1
                if step==0: continue
                path=list(range(s,r2+step,step))
                if not all(clean(p,c) for p,c in zip(path,[ca if False else None])): pass
        # simple: walk vertically from each segment end toward r
        for name,S,(top,bot) in [('A',A,(ra,ra)),('B',B,(rb,rb))]:
            pass
        # try both directions from each segment to r
        for S,name in [(A,'A'),(B,'B')]:
            top_=min(p[0] for p in S[2]); bot_=max(p[0] for p in S[2])
            for s in [top_,bot_]:
                st=s
                while st!=r and clean(st,ca): st+=1
                if st!=r and st>r: continue
                if st==r:
                    cells_leg=[]
                    for q in range(min(top_,r),max(top_,r)+1):
                        if q!=s and clean(q,ca): cells_leg.append(q)
                    if cells_leg:
                        legok2=True
                        for q in cells_leg:
                            pass
                        # check column leg doesn't overlap segments
                        if all(not (q>=top_ and q<=bot_) for q in cells_leg):
                            pass
                    if True: break
        # verify legs don't collide with segments: column from min(seg) to r
        c2=ca
        s1,s2=A if ca!=cb else B
        for q in range(min(top_,r),max(top_,r)+1):
            if not clean(q,c2) and q not in [p[0] for p in S[2]]: legok=False; break
        if legok and best is None or (legok and (best is None or r>best[0])):
            best=(r,c2,c1)
    if best is None: return inp
    r,c0,c1=best
    out=[row[:] for row in inp]
    S_legs=[]
    # fill legs and corridor; avoid painting over segments
    for S,top_,bot_ in [(A,ra,ra),(B,rb,rb)]:
        for q in range(min(top_,r),max(top_,r)+1):
            if q not in [p[0] for p in S[2]] and clean(q,c0): out[q][c0]=3
        for q in range(max(top_,r),min(bot_,r)+1):
            if q not in [p[0] for p in S[2]] and clean(q,c1): out[q][c1]=3
    for q in range(c0,c1+1):
        if clean(r,q): out[r][q]=3
    return out
