def f(gi):
    h=len(gi); w=len(gi[0])
    cnt=Counter(v for row in gi for v in row)
    bg=cnt.most_common(1)[0][0]
    specials=[c for c,n in cnt.items() if n<=3 and c!=bg]
    sA=sorted((r,c) for r in range(h) for c in range(w) if gi[r][c]==specials[0])
    sB=sorted((r,c) for r in range(h) for c in range(w) if gi[r][c]==specials[1])
    out=[row[:] for row in gi]
    def mark(r,c,v):
        if out[r][c]!=v: out[r][c]=v
    A_cols={c for r,c in sA}; B_cols={c for r,c in sB}
    A_rows=set(sA); B_rows=set(sB)
    # vertical segments: constant col, varying row
    print('sA',sA,'sB',sB)
    # arm_r = just below A bottom if A above B else just above A top
    if min(B_rows)>max(A_rows):
        arm_r=max(A_rows)+1
    else:
        arm_r=min(A_rows)-1
    # horizontal arm from A's column end toward B column
    arm_col = list(A_cols)[0]
    bc=list(B_cols)[0]
    for c in range(min(arm_col,bc), max(arm_col,bc)):
        mark(arm_r, c, 3)
    # vertical leg at B column, from arm_r to adjacent of B segment
    br_min=min(B_rows); br_max=max(B_rows)
    if arm_r < br_min:
        for r in range(arm_r+1, br_min):
            mark(r, bc, 3)
    elif arm_r > br_max:
        for r in range(br_max+1, arm_r-1):
            mark(r, bc, 3)
    return out
