import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps_of(g,color,H,W):
    seen=set();out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==color and (r,c) not in seen:
                st=[(r,c)];seen.add((r,c));cp=[]
                while st:
                    y,x=st.pop();cp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<H and 0<=b<W and g[a][b]==color and (a,b) not in seen:
                            seen.add((a,b));st.append((a,b))
                out.append(cp)
    return out
for i in range(4,8):
    gi=G[f'Demo pair {i} input']; go=G[f'Demo pair {i} output']
    H,W=len(gi),len(gi[0])
    bg=max(set(v for row in gi for v in row), key=lambda c: sum(row.count(c) for row in gi))
    A=comps_of(gi,2,H,W)[0]; B=comps_of(gi,3,H,W)[0]
    Ar=[(r,c) for r,c in A]; Br=[(r,c) for r,c in B]
    added=[(r,c) for r in range(H) for c in range(W) if go[r][c]==3 and gi[r][c]!=3]
    # orientation: vertical bar = same col, horizontal = same row
    vertA = len({c for r,c in A})==1; vertB = len({c for r,c in B})==1
    # endpoints sorted by distance along axis
    def sort_along(cells, vert):
        return sorted(cells, key=lambda p: p[0] if vert else p[1])
    A1,A2=sort_along(A,vertA); B1,B2=sort_along(B,vertB)
    print(f'd{i}: A={A1},{A2}; B={B1},{B2}')
    # group added cells into runs
    used=set(); segs=[]
    for (r,c) in sorted(added):
        if (r,c) in used: continue
        q=[(r,c)]; used.add((r,c)); cur=q
        while True:
            hit=False
            for j in range(len(segs)):
                sq=segs[j]
                (rr,cc)=(sq[-1][0],sq[-1][1])
                if abs(rr-r)<=1 and abs(cc-c)<=1:
                    if cc==c:
                        nq=sq+[p for p in [(r,c)] if False]+[(r,c)] if False else sq+[(r,c)]
                        if all(go[y][x]==3 and gi[y][x]!=3 for y,x in nq):
                            segs[j]=nq; used|=set(sq); hit=True
                    elif rr==r:
                        nq=sq+[(r,c)]
                        if all(go[y][x]==3 and gi[y][x]!=3 for y,x in nq):
                            segs[j]=nq; used|=set(sq); hit=True
            if not hit: break
        segs.append(q)
    for s_ in segs:
        rs=sorted({p[0] for p in s_}); cs=sorted({p[1] for p in s_})
        typ='horz' if len(rs)==1 else ('vert' if len(cs)==1 else 'diagonalsplit')
        print('   ',typ,'rows',rs,'cols',cs,'cells',s_)
